/// A p0 phone tool (SPEC-10 r3). A closed union: p1 tools are added here as new variants, so the Mac brain only ever calls tools whose arguments it can check.
public enum PhoneToolCall: Codable, Equatable, Sendable {
    case setAlarm(SetAlarmCall)
    case setTimer(SetTimerCall)
    case openApp(PhoneOpenAppCall)

    private enum DiscriminatorKey: String, CodingKey {
        case discriminator = "tool"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: DiscriminatorKey.self)
        let value = try container.decode(String.self, forKey: .discriminator)
        switch value {
        case "set_alarm": self = .setAlarm(try SetAlarmCall(from: decoder))
        case "set_timer": self = .setTimer(try SetTimerCall(from: decoder))
        case "open_app": self = .openApp(try PhoneOpenAppCall(from: decoder))
        default:
            throw DecodingError.dataCorruptedError(forKey: .discriminator, in: container, debugDescription: "Unknown PhoneToolCall tool: \(value)")
        }
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: DiscriminatorKey.self)
        switch self {
        case .setAlarm(let value):
            try container.encode("set_alarm", forKey: .discriminator)
            try value.encode(to: encoder)
        case .setTimer(let value):
            try container.encode("set_timer", forKey: .discriminator)
            try value.encode(to: encoder)
        case .openApp(let value):
            try container.encode("open_app", forKey: .discriminator)
            try value.encode(to: encoder)
        }
    }
}

