/// One call to a typed tool.
public enum ToolCall: Codable, Equatable, Sendable {
    case openApp(OpenAppCall)
    case openFile(OpenFileCall)
    case openUrl(OpenUrlCall)
    case revealInFinder(RevealInFinderCall)
    case readFile(ReadFileCall)
    case listDir(ListDirCall)
    case writeNewFile(WriteNewFileCall)
    case copy(CopyCall)
    case move(MoveCall)
    case moveToTrash(MoveToTrashCall)
    case phone(PhoneCall)

    private enum DiscriminatorKey: String, CodingKey {
        case discriminator = "tool"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: DiscriminatorKey.self)
        let value = try container.decode(String.self, forKey: .discriminator)
        switch value {
        case "open_app": self = .openApp(try OpenAppCall(from: decoder))
        case "open_file": self = .openFile(try OpenFileCall(from: decoder))
        case "open_url": self = .openUrl(try OpenUrlCall(from: decoder))
        case "reveal_in_finder": self = .revealInFinder(try RevealInFinderCall(from: decoder))
        case "read_file": self = .readFile(try ReadFileCall(from: decoder))
        case "list_dir": self = .listDir(try ListDirCall(from: decoder))
        case "write_new_file": self = .writeNewFile(try WriteNewFileCall(from: decoder))
        case "copy": self = .copy(try CopyCall(from: decoder))
        case "move": self = .move(try MoveCall(from: decoder))
        case "move_to_trash": self = .moveToTrash(try MoveToTrashCall(from: decoder))
        case "phone": self = .phone(try PhoneCall(from: decoder))
        default:
            throw DecodingError.dataCorruptedError(forKey: .discriminator, in: container, debugDescription: "Unknown ToolCall tool: \(value)")
        }
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: DiscriminatorKey.self)
        switch self {
        case .openApp(let value):
            try container.encode("open_app", forKey: .discriminator)
            try value.encode(to: encoder)
        case .openFile(let value):
            try container.encode("open_file", forKey: .discriminator)
            try value.encode(to: encoder)
        case .openUrl(let value):
            try container.encode("open_url", forKey: .discriminator)
            try value.encode(to: encoder)
        case .revealInFinder(let value):
            try container.encode("reveal_in_finder", forKey: .discriminator)
            try value.encode(to: encoder)
        case .readFile(let value):
            try container.encode("read_file", forKey: .discriminator)
            try value.encode(to: encoder)
        case .listDir(let value):
            try container.encode("list_dir", forKey: .discriminator)
            try value.encode(to: encoder)
        case .writeNewFile(let value):
            try container.encode("write_new_file", forKey: .discriminator)
            try value.encode(to: encoder)
        case .copy(let value):
            try container.encode("copy", forKey: .discriminator)
            try value.encode(to: encoder)
        case .move(let value):
            try container.encode("move", forKey: .discriminator)
            try value.encode(to: encoder)
        case .moveToTrash(let value):
            try container.encode("move_to_trash", forKey: .discriminator)
            try value.encode(to: encoder)
        case .phone(let value):
            try container.encode("phone", forKey: .discriminator)
            try value.encode(to: encoder)
        }
    }
}

