}

/// A device the relay refused with unsupportedVersion tries again every 5 minutes and when the app starts, instead of reconnecting with backoff, keeping its keys and pairings (OBJ-34).
public let UNSUPPORTED_VERSION_RETRY_SECONDS: Int = 300

/// An error the user will see. Apps turn it into the SPEC-11 copy. Technical details go to the local log, not here.
public struct UserError: Codable, Equatable, Sendable {
    public var kind: ErrorKind
    public var taskId: String?
    /// Fills {device} in the copy: the other device.
    public var device: String?
    /// Fills {last action} in the Unexpected copy, from the action log. Absent when nothing has run yet; the copy then drops that sentence and the Show what I did button.
    public var lastAction: String?
    /// Fills {permission} in the Android permission copy with a plain name, for example location or camera.
    public var permission: String?
    /// Fills {step} in the stepFailed copy: the title of the subtask that could not finish, as the user would say it (SPEC-11 r14).
    public var step: String?
    /// For taskTookTooLong: what was finished.
    public var finishedSoFar: String?
    /// Fills {action} in the blockedAction copy (SPEC-07 r5): the action that was blocked and skipped, in plain language as a verb phrase after I can't, for example click File in Keynote or press Command-Q in Keynote. Built from the action and the real element, never from model text, and never holding text Yumi would type. Absent when there is no plain name for it; the copy then says that.
    public var skippedAction: String?

    public init(kind: ErrorKind, taskId: String? = nil, device: String? = nil, lastAction: String? = nil, permission: String? = nil, step: String? = nil, finishedSoFar: String? = nil, skippedAction: String? = nil) {
        self.kind = kind
        self.taskId = taskId
        self.device = device
        self.lastAction = lastAction
        self.permission = permission
        self.step = step
        self.finishedSoFar = finishedSoFar
        self.skippedAction = skippedAction
    }
}

